// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 _value) public {
        vm.assume(_value > 0 && _value <= type(uint256).max / 2);
        vm.prank(address(this));
        c.mintToken(address(this), _value);
        uint256 totalSupplyBefore = c.totalSupply();
        vm.prank(address(this));
        bool ok;
        try c.burn(_value) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }
        vm.assume(ok);
        uint256 totalSupplyAfter = c.totalSupply();
        assertTrue(totalSupplyBefore - totalSupplyAfter == _value);
    }
}
